import { FormEvent, useMemo, useState } from 'react'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { useNavigate } from 'react-router-dom'
import { Activity, ArrowDownLeft, ArrowUpRight, BellRing, Check, ChevronRight, Clock3, Download, FileBarChart, FileSpreadsheet, FileText, Filter, MoreHorizontal, Paperclip, Pencil, Plus, Search, ShieldCheck, TrendingUp, Upload, Users, Wallet, X } from 'lucide-react'
import { Bar, BarChart, CartesianGrid, Cell, Legend, Line, LineChart, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts'
import { api, dateLabel, download, money, queryString, shortMoney } from '../lib/api'
import type { Activity as ActivityType, Alert, Category, Client, DashboardData, Filters, Kpis, Transaction } from '../lib/types'
import { periodParams, useFilters } from '../components/Layout'
import { AddButton, Button, EmptyState, ErrorState, LoadingState, MetricCard, Modal, Money, Panel, SectionTitle } from '../components/ui'

const chartColors = ['#E8763A','#30302E','#5D8F88','#E8B36B','#A9A39B','#8296B0']
const paymentMethods = [['orange_money','Orange Money'],['moov_money','Moov Money'],['coris','Coris'],['bank_transfer','Virement'],['cash','Espèces'],['other','Autre']]
const methodLabel = (key?:string) => paymentMethods.find(([id])=>id===key)?.[1] || key || '—'
const statusLabel: Record<string,string> = {received:'Reçu',pending:'En attente',overdue:'En retard',draft:'Brouillon',sent:'Envoyé',accepted:'Accepté',rejected:'Refusé',expired:'Expiré',issued:'Émise',paid:'Payée'}
const qParams = (filters: Filters) => queryString(periodParams(filters))
const invalidate = (client: ReturnType<typeof useQueryClient>, keys: string[][]) => keys.forEach(key => client.invalidateQueries({queryKey:key}))

export function DashboardPage() {
  const filters = useFilters()
  const params = qParams(filters)
  const query = useQuery({queryKey:['dashboard', params], queryFn:()=>api<DashboardData>(`/dashboard${params}`)})
  const navigate = useNavigate()
  if(query.isLoading) return <LoadingState/>
  if(query.error) return <ErrorState error={query.error}/>
  const data = query.data!
  const k = data.kpis
  const bars = k.monthly.map(m => ({...m, name:new Date(`${m.month}-01T12:00:00`).toLocaleDateString('fr-FR',{month:'short'})}))
  const revenueLine = k.monthly.map(m => ({name:m.month, revenus:m.income_xof, depenses:m.expenses_xof, net:m.income_xof-m.expenses_xof}))
  const spark = (key:'income_xof'|'expenses_xof') => k.monthly.map(m=>m[key])
  const periodTarget = filters.period.startsWith('M') ? (data.settings.monthly_target_xof||0) : filters.period.startsWith('Q') ? (data.settings.monthly_target_xof||0)*3 : (data.settings.annual_target_xof||0)
  const targetLabel = filters.period.startsWith('M') ? 'Objectif mensuel' : filters.period.startsWith('Q') ? 'Objectif trimestriel' : 'Objectif annuel'
  const values: [string,number,number|null,string,'orange'|'green'|'ink'|'blue',number[]][] = [
    ['CA encaissé',k.revenue_xof,k.changes.revenue_pct,'vs période précédente','orange',spark('income_xof')],
    ['Dépenses',k.expenses_xof,k.changes.expenses_pct,'charges réglées','ink',spark('expenses_xof')],
    ['Résultat net',k.net_profit_xof,k.changes.profit_pct,'encaissements − dépenses','green',revenueLine.map(x=>x.net)],
    ['Trésorerie',k.cash_balance_xof,null,'solde cumulé estimé','blue',revenueLine.map(x=>x.net)],
  ]
  return <div className="page-stack">
    {data.alerts.length>0 && <div className="alert-ribbon"><div className="ribbon-icon"><BellRing size={17}/></div><div><strong>{data.alerts.length} point{data.alerts.length>1?'s':''} à surveiller</strong><span>{data.alerts[0].title} · {data.alerts[0].recommendation}</span></div><button onClick={()=>navigate('/alerts')}>Voir les alertes <ChevronRight size={15}/></button></div>}
    <div className="metric-grid">{values.map(([label,value,change,detail,color,series],i)=><MetricCard key={label} label={label} value="" numeric={value} change={change} detail={detail} color={color} data={series}/>)}</div>
    <div className="metric-subgrid"><div className="submetric"><span>Créances en attente</span><strong>{money(k.receivables_xof)}</strong><small>{money(k.overdue_xof)} en retard</small></div><div className="submetric"><span>Marge nette</span><strong>{k.net_margin_pct.toLocaleString('fr-FR')}<i>%</i></strong><small>résultat net / CA encaissé</small></div><div className="submetric"><span>Taux d’épargne</span><strong>{k.savings_rate_pct.toLocaleString('fr-FR')}<i>%</i></strong><small>sur les encaissements reçus</small></div><div className="submetric"><span>CA facturé</span><strong>{money(k.billed_revenue_xof)}</strong><small>DSO moyen : {k.dso_days} jours</small></div></div>
    <Panel className="goal-panel"><div className="goal-title"><div><div className="eyebrow">CAP FINANCIER</div><h2>Votre rythme, vos objectifs.</h2><p>Suivez la progression de vos encaissements sur la période sélectionnée.</p></div><div className="goal-badge"><TrendingUp size={16}/><span>{targetLabel}</span></div></div><GoalProgress label={targetLabel} actual={k.revenue_xof} target={periodTarget}/><GoalProgress label="Objectif mensuel de référence" actual={k.monthly.length?k.monthly[k.monthly.length-1].income_xof:k.revenue_xof} target={data.settings.monthly_target_xof||0}/></Panel>
    <div className="dashboard-grid dashboard-grid-main">
      <Panel className="chart-panel"><SectionTitle title="Mouvement de trésorerie" subtitle="Encaissements et dépenses réglés · mensuel" action={<span className="panel-badge"><i/> DONNÉES RÉELLES</span>}/><div className="chart-legend"><span><i className="legend-orange"/> Revenus</span><span><i className="legend-ink"/> Dépenses</span></div><div className="chart-large"><ResponsiveContainer width="100%" height="100%"><BarChart data={bars} barGap={6} margin={{top:10,right:8,left:0,bottom:0}}><CartesianGrid vertical={false} stroke="var(--line)" strokeDasharray="4 5"/><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill:'var(--muted)',fontSize:11}}/><YAxis axisLine={false} tickLine={false} tick={{fill:'var(--muted)',fontSize:10}} tickFormatter={shortMoney} width={42}/><Tooltip formatter={(v:any)=>money(Number(v))}/><Bar dataKey="income_xof" name="Revenus" fill="#E8763A" radius={[5,5,1,1]} maxBarSize={26}/><Bar dataKey="expenses_xof" name="Dépenses" fill="#262624" radius={[5,5,1,1]} maxBarSize={26}/></BarChart></ResponsiveContainer></div><div className="chart-insight"><span className="insight-mark"><TrendingUp size={15}/></span><span>Le CA facturé représente <b>{k.quote_conversion_pct}%</b> de conversion des devis. Panier encaissé moyen : <b>{money(k.average_basket_xof)}</b>.</span></div></Panel>
      <Panel className="activity-panel"><SectionTitle title="Performance par activité" subtitle="Répartition des revenus encaissés" action={<button className="more-button" aria-label="Plus d'options"><MoreHorizontal size={18}/></button>}/>{k.activities.length?<><div className="donut-wrap"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={k.activities} dataKey="revenue_xof" nameKey="activity_name" innerRadius={66} outerRadius={92} paddingAngle={4} stroke="none">{k.activities.map((_,i)=><Cell key={i} fill={chartColors[i%chartColors.length]}/>)}</Pie><Tooltip formatter={(v:any)=>money(Number(v))}/></PieChart></ResponsiveContainer><div className="donut-center"><span>CA TOTAL</span><strong>{shortMoney(k.revenue_xof)}</strong><small>FCFA</small></div></div><div className="activity-list">{k.activities.slice(0,5).map((a,i)=><div className="activity-item" key={a.activity_id}><span className="activity-dot" style={{background:chartColors[i%chartColors.length]}}/><span className="activity-name">{a.activity_name}</span><strong>{money(a.revenue_xof)}</strong><small>{k.revenue_xof?Math.round(100*a.revenue_xof/k.revenue_xof):0}%</small></div>)}</div></>:<EmptyState title="Aucune activité" text="Ajoutez une activité et reliez-y vos transactions." icon={Activity}/>}</Panel>
    </div>
    <div className="dashboard-grid dashboard-grid-secondary">
      <Panel className="trend-panel"><SectionTitle title="Tendance du résultat" subtitle="Net mensuel estimé sur la période"/><div className="chart-medium"><ResponsiveContainer width="100%" height="100%"><LineChart data={revenueLine} margin={{top:14,right:8,left:0,bottom:0}}><CartesianGrid vertical={false} stroke="var(--line)" strokeDasharray="4 5"/><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill:'var(--muted)',fontSize:10}} tickFormatter={(x:string)=>x.slice(5)}/><YAxis axisLine={false} tickLine={false} tick={{fill:'var(--muted)',fontSize:10}} tickFormatter={shortMoney} width={42}/><Tooltip formatter={(v:any)=>money(Number(v))}/><Line type="monotone" dataKey="net" name="Résultat net" stroke="#E8763A" strokeWidth={2.7} dot={{r:3,fill:'#E8763A',strokeWidth:0}} activeDot={{r:5}}/></LineChart></ResponsiveContainer></div><div className="chart-footnote">Les factures non encaissées sont présentées dans les créances.</div></Panel>
      <Panel className="top-clients-panel"><SectionTitle title="Top clients" subtitle="Par encaissements sur la période" action={<button className="text-link" onClick={()=>navigate('/clients')}>Tout voir <ChevronRight size={14}/></button>}/>{k.top_clients.length?<div className="top-clients-list">{k.top_clients.map((client,i)=><div className="top-client" key={client.client_id}><div className={`client-rank rank-${i+1}`}>{String(i+1).padStart(2,'0')}</div><div className="top-client-main"><strong>{client.client_name}</strong><div className="client-bar"><span style={{width:`${Math.max(5,100*client.revenue_xof/Math.max(1,k.top_clients[0].revenue_xof))}%`}}/></div></div><b>{money(client.revenue_xof)}</b></div>)}</div>:<EmptyState/>}</Panel>
    </div>
    <Panel className="transactions-panel"><SectionTitle title="Dernières transactions" subtitle="Activité récente dans votre registre" action={<button className="text-link" onClick={()=>navigate('/transactions')}>Voir le registre <ChevronRight size={14}/></button>}/><TransactionTable rows={data.recent_transactions} compact/></Panel>
    {data.budgets.length>0 && <Panel><SectionTitle title="Budget vs réel" subtitle="Dépenses enregistrées sur la période"/><BudgetRows rows={data.budgets}/></Panel>}
  </div>
}

function TransactionTable({rows,compact=false,onEdit,onDelete}: {rows:Transaction[];compact?:boolean;onEdit?:(t:Transaction)=>void;onDelete?:(t:Transaction)=>void}) {
  const acts = useQuery({queryKey:['activities'],queryFn:()=>api<ActivityType[]>('/activities')}).data || []
  const clients = useQuery({queryKey:['clients','filter'],queryFn:()=>api<Client[]>('/clients')}).data || []
  const cats = useQuery({queryKey:['categories'],queryFn:()=>api<Category[]>('/categories')}).data || []
  if(!rows.length) return <EmptyState title="Aucune transaction" text="Ajoutez une entrée ou une dépense pour commencer votre suivi." icon={ArrowDownLeft}/>
  return <div className="table-scroll"><table className="data-table"><thead><tr><th>TRANSACTION</th><th>ACTIVITÉ / CLIENT</th><th>CATÉGORIE</th><th>DATE</th><th>STATUT</th><th className="align-right">MONTANT</th>{!compact&&<><th>PIÈCES</th><th/></>}</tr></thead><tbody>{rows.map(row=><tr key={row.id}><td><div className="transaction-title"><span className={`transaction-icon ${row.kind}`} aria-hidden>{row.kind==='income'?<ArrowDownLeft size={15}/>:<ArrowUpRight size={15}/>}</span><div><strong>{row.description || (row.kind==='income'?'Encaissement':'Dépense')}</strong><small>{methodLabel(row.payment_method)}</small></div></div></td><td><div className="two-line"><strong>{acts.find(a=>a.id===row.activity_id)?.name || 'Non affecté'}</strong><small>{clients.find(c=>c.id===row.client_id)?.name || '—'}</small></div></td><td>{cats.find(c=>c.id===row.category_id)?.name || '—'}</td><td>{dateLabel(row.transaction_date)}</td><td><span className={`status-pill status-${row.status}`}>{statusLabel[row.status] || row.status}</span></td><td className={`amount-cell ${row.kind==='income'?'income-text':'expense-text'}`}>{row.kind==='income'?'+':'−'}{money(row.amount_xof)}</td>{!compact&&<><td><AttachmentCell transactionId={row.id}/></td><td><div className="row-actions"><button className="icon-button small" onClick={()=>onEdit?.(row)} title="Modifier"><Pencil size={14}/></button><button className="icon-button small danger-hover" onClick={()=>onDelete?.(row)} title="Supprimer"><X size={15}/></button></div></td></>}</tr>)}</tbody></table></div>
}

function AttachmentCell({transactionId}:{transactionId:string}) {
  const client=useQueryClient();const [open,setOpen]=useState(false)
  const query=useQuery({queryKey:['attachments',transactionId],queryFn:()=>api<any[]>(`/transactions/${transactionId}/attachments`),enabled:open})
  const upload=useMutation({mutationFn:async(file:File)=>{const form=new FormData();form.append('file',file);return api(`/transactions/${transactionId}/attachments`,{method:'POST',body:form})},onSuccess:()=>client.invalidateQueries({queryKey:['attachments',transactionId]})})
  return <div className="attachment-actions"><button className="icon-button small" title="Voir les pièces jointes" onClick={()=>setOpen(v=>!v)}><Paperclip size={14}/></button><label className="icon-button small attachment-upload" title="Ajouter une pièce jointe"><Upload size={13}/><input type="file" onChange={e=>{const file=e.target.files?.[0];if(file)upload.mutate(file);e.currentTarget.value=''}}/></label>{open&&<div className="attachment-popover">{query.isLoading?'Chargement…':query.data?.length?query.data.map(file=><button key={file.id} onClick={()=>void download(`/attachments/${file.id}`,file.filename)}><Download size={12}/>{file.filename}</button>):<span>Aucune pièce jointe</span>}</div>}</div>
}

export function TransactionsPage() {
  const filters = useFilters(); const params = queryString({...periodParams(filters), ...(filters.period.startsWith('Q')?{quarter:Number(filters.period.slice(1))}:{})})
  const client = useQueryClient(); const [modal,setModal] = useState(false); const [editing,setEditing] = useState<Transaction|null>(null); const [search,setSearch] = useState(''); const [kind,setKind] = useState(''); const [importResult,setImportResult] = useState<any>(null)
  const rowsQuery = useQuery({queryKey:['transactions',params,kind,search],queryFn:()=>api<Transaction[]>(`/transactions${queryString({...periodParams(filters),kind,search})}`)})
  const activities = useQuery({queryKey:['activities'],queryFn:()=>api<ActivityType[]>('/activities')}).data||[]
  const clients = useQuery({queryKey:['clients','filter'],queryFn:()=>api<Client[]>('/clients')}).data||[]
  const categories = useQuery({queryKey:['categories'],queryFn:()=>api<Category[]>('/categories')}).data||[]
  const save = useMutation({mutationFn:(data:any)=>api(`/transactions${editing?`/${editing.id}`:''}`,{method:editing?'PUT':'POST',body:JSON.stringify(data)}),onSuccess:()=>{setModal(false);setEditing(null);invalidate(client,[['transactions'],['dashboard']])}})
  const remove = useMutation({mutationFn:(id:string)=>api(`/transactions/${id}`,{method:'DELETE'}),onSuccess:()=>invalidate(client,[['transactions'],['dashboard']])})
  const doImport = async(file:File)=>{const form=new FormData();form.append('file',file);const result=await api<any>('/transactions/import-csv',{method:'POST',body:form});setImportResult(result);invalidate(client,[['transactions'],['dashboard']])}
  const startEdit=(t:Transaction)=>{setEditing(t);setModal(true)}
  if(rowsQuery.isLoading)return <LoadingState/>
  if(rowsQuery.error)return <ErrorState error={rowsQuery.error}/>
  const rows=rowsQuery.data||[]; const income=rows.filter(r=>r.kind==='income'&&r.status==='received').reduce((s,r)=>s+r.amount_xof,0); const outflow=rows.filter(r=>r.kind==='expense'&&r.status==='received').reduce((s,r)=>s+r.amount_xof,0)
  return <div className="page-stack"><div className="inline-stats"><div><span>Entrées reçues</span><strong className="income-text">{money(income)}</strong></div><div><span>Sorties réglées</span><strong>{money(outflow)}</strong></div><div><span>Transactions visibles</span><strong>{rows.length}</strong></div><div className="inline-actions"><label className="button button-secondary import-button"><Upload size={15}/> Importer CSV<input type="file" accept=".csv,text/csv" onChange={e=>{if(e.target.files?.[0])void doImport(e.target.files[0])}}/></label><Button variant="secondary" onClick={()=>void download('/transactions/export-csv','finpilot-transactions.csv')}><Download size={15}/> Exporter</Button><AddButton onClick={()=>{setEditing(null);setModal(true)}}>Nouvelle entrée</AddButton></div></div>
    {importResult&&<div className="import-result"><Check size={15}/> {importResult.created} ajoutée(s), {importResult.duplicates} doublon(s), {importResult.errors} erreur(s).<button onClick={()=>setImportResult(null)}><X size={14}/></button></div>}
    <Panel><div className="table-toolbar"><div><SectionTitle title="Registre financier" subtitle="Revenus, dépenses et mouvements à venir"/></div><div className="toolbar-filters"><label className="search-box"><Search size={15}/><input placeholder="Rechercher une transaction" value={search} onChange={e=>setSearch(e.target.value)}/></label><label className="select-filter"><Filter size={14}/><select value={kind} onChange={e=>setKind(e.target.value)}><option value="">Tous les flux</option><option value="income">Revenus</option><option value="expense">Dépenses</option></select></label></div></div><TransactionTable rows={rows} onEdit={startEdit} onDelete={row=>{if(window.confirm(`Supprimer « ${row.description} » ?`))remove.mutate(row.id)}}/></Panel>
    {modal&&<TransactionModal initial={editing} activities={activities} clients={clients} categories={categories} pending={save.isPending} error={save.error} onClose={()=>{setModal(false);setEditing(null)}} onSave={data=>save.mutate(data)}/>}
  </div>
}

function TransactionModal({initial,activities,clients,categories,pending,error,onClose,onSave}:{initial:Transaction|null;activities:ActivityType[];clients:Client[];categories:Category[];pending:boolean;error:unknown;onClose:()=>void;onSave:(data:any)=>void}) {
  const [kind,setKind]=useState<'income'|'expense'>(initial?.kind||'income')
  const formSubmit=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);onSave({kind,amount_xof:Number(f.get('amount_xof')),transaction_date:f.get('transaction_date'),due_date:f.get('due_date')||null,status:f.get('status'),payment_method:f.get('payment_method')||null,activity_id:f.get('activity_id')||null,client_id:f.get('client_id')||null,category_id:f.get('category_id')||null,description:f.get('description'),reference:f.get('reference')||null})}
  return <Modal title={initial?'Modifier la transaction':'Nouvelle transaction'} subtitle="Les montants sont saisis en FCFA." onClose={onClose}><form className="form-grid" onSubmit={formSubmit}><div className="segmented full-span"><button type="button" className={kind==='income'?'selected':''} onClick={()=>setKind('income')}><ArrowDownLeft size={15}/> Revenu</button><button type="button" className={kind==='expense'?'selected':''} onClick={()=>setKind('expense')}><ArrowUpRight size={15}/> Dépense</button></div><label className="field-label">Montant (FCFA)<input name="amount_xof" type="number" min="1" defaultValue={initial?.amount_xof} required placeholder="250000"/></label><label className="field-label">Date<input name="transaction_date" type="date" defaultValue={initial?.transaction_date} required/></label><label className="field-label">Statut<select name="status" defaultValue={initial?.status||'received'}><option value="received">Reçu / réglé</option><option value="pending">En attente</option><option value="overdue">En retard</option></select></label><label className="field-label">Échéance<input name="due_date" type="date" defaultValue={initial?.due_date||''}/></label><label className="field-label">Catégorie<select name="category_id" defaultValue={initial?.category_id||''}><option value="">Sans catégorie</option>{categories.filter(c=>c.kind===kind).map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label className="field-label">Activité<select name="activity_id" defaultValue={initial?.activity_id||''}><option value="">Non affecté</option>{activities.map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</select></label><label className="field-label">Client<select name="client_id" defaultValue={initial?.client_id||''}><option value="">Sans client</option>{clients.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label className="field-label">Moyen de paiement<select name="payment_method" defaultValue={initial?.payment_method||''}><option value="">Non renseigné</option>{paymentMethods.map(([id,label])=><option key={id} value={id}>{label}</option>)}</select></label><label className="field-label full-span">Description<input name="description" defaultValue={initial?.description||''} required placeholder="Ex. Accompagnement mensuel"/></label><label className="field-label full-span">Référence (facultatif)<input name="reference" defaultValue={initial?.reference||''} placeholder="N° reçu, référence bancaire…"/></label>{error!=null&&<div className="full-span"><ErrorState error={error}/></div>}<div className="form-actions full-span"><Button type="button" variant="secondary" onClick={onClose}>Annuler</Button><Button type="submit" disabled={pending}>{pending?'Enregistrement…':'Enregistrer'}</Button></div></form></Modal>
}

function BudgetRows({rows}:{rows:DashboardData['budgets']}) {
  return <div className="budget-list">{rows.map(row=>{const pct=Math.min(100,Math.round(100*row.actual_xof/Math.max(1,row.budget_xof)));return <div className="budget-row" key={row.category_name}><div><strong>{row.category_name}</strong><span>{money(row.actual_xof)} / {money(row.budget_xof)}</span></div><div className="budget-track"><span className={pct>90?'warn':''} style={{width:`${pct}%`}}/></div><b>{pct}%</b></div>})}</div>
}

function GoalProgress({label,actual,target}:{label:string;actual:number;target:number}) {
  const pct=target?Math.round(100*actual/target):0
  return <div className="goal-progress"><div><span>{label}</span><strong>{money(actual)} <small>sur {money(target)}</small></strong></div><div className="goal-track"><span style={{width:`${Math.max(0,Math.min(100,pct))}%`}}/></div><b>{pct}%</b></div>
}

export function ClientsPage() {
  const client=useQueryClient(); const [search,setSearch]=useState(''); const [modal,setModal]=useState(false); const [selected,setSelected]=useState<string|null>(null)
  const query=useQuery({queryKey:['clients',search],queryFn:()=>api<Client[]>(`/clients${queryString({search})}`)})
  const detail=useQuery({queryKey:['client-detail',selected],queryFn:()=>api<any>(`/clients/${selected}`),enabled:!!selected})
  const save=useMutation({mutationFn:(data:any)=>api('/clients',{method:'POST',body:JSON.stringify(data)}),onSuccess:()=>{setModal(false);invalidate(client,[['clients']])}})
  if(query.isLoading)return <LoadingState/>;if(query.error)return <ErrorState error={query.error}/>
  const clients=query.data||[];const total=clients.reduce((s,c)=>s+c.revenue_xof,0);const open=clients.reduce((s,c)=>s+c.receivables_xof,0)
  return <div className="page-stack"><div className="inline-stats"><div><span>Clients actifs</span><strong>{clients.length}</strong></div><div><span>CA encaissé total</span><strong>{money(total)}</strong></div><div><span>Solde à recouvrer</span><strong className={open?'warning-text':''}>{money(open)}</strong></div><div className="inline-actions"><label className="search-box"><Search size={15}/><input placeholder="Rechercher un client" value={search} onChange={e=>setSearch(e.target.value)}/></label><AddButton onClick={()=>setModal(true)}>Nouveau client</AddButton></div></div>
    <div className="clients-layout"><Panel className="clients-panel"><SectionTitle title="Portefeuille clients" subtitle="Contribution estimée par chiffre d’affaires encaissé"/><div className="table-scroll"><table className="data-table"><thead><tr><th>CLIENT</th><th>SEGMENT</th><th>CA ENCAISSÉ</th><th>FACTURÉ</th><th>SOLDE DÛ</th><th>DÉLAI</th><th>FIABILITÉ</th></tr></thead><tbody>{clients.map((c,i)=><tr key={c.id} className={selected===c.id?'row-selected':''} onClick={()=>setSelected(c.id)}><td><div className="client-cell"><div className={`client-avatar avatar-color-${i%5}`}>{c.name.split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase()}</div><div><strong>{c.name}</strong><small>{c.email || c.phone || 'Client'}</small></div></div></td><td><span className={`segment-badge segment-${c.segment.toLowerCase()}`}>Segment {c.segment}</span></td><td className="amount-cell">{money(c.revenue_xof)}</td><td>{money(c.billed_xof)}</td><td className={c.receivables_xof?'warning-text':''}>{money(c.receivables_xof)}</td><td>{c.average_payment_days===null||c.average_payment_days===undefined?'—':`${c.average_payment_days} j`}</td><td><span className="rating">{'★'.repeat(c.reliability_score||0)}<i>{'☆'.repeat(5-(c.reliability_score||0))}</i></span></td></tr>)}</tbody></table>{!clients.length&&<EmptyState title="Votre portefeuille démarre ici" text="Ajoutez vos clients pour mesurer leur contribution et suivre les créances." icon={Users}/>}</div><div className="table-note"><span>Segmentation calculée sur le CA encaissé cumulé : A jusqu’à 80 %, B jusqu’à 95 %, C au-delà.</span></div></Panel>
      <Panel className="client-side-panel">{selected&&detail.data?<><SectionTitle title="Fiche client" action={<button className="icon-button small" onClick={()=>setSelected(null)} aria-label="Fermer"><X size={15}/></button>}/><div className="client-detail-head"><div className="client-avatar avatar-color-2 large-avatar">{detail.data.client.name.slice(0,2).toUpperCase()}</div><div><h3>{detail.data.client.name}</h3><p>{detail.data.client.email||'Coordonnées non renseignées'}</p></div></div><div className="client-detail-metrics"><div><span>CA encaissé</span><b>{money(detail.data.revenue_xof)}</b></div><div><span>Marge de trésorerie</span><b>{money(detail.data.revenue_xof-detail.data.expenses_xof)}</b></div><div><span>Solde dû</span><b className="warning-text">{money(detail.data.receivables_xof)}</b></div><div><span>Délai convenu</span><b>{detail.data.client.payment_terms_days} jours</b></div></div><h4 className="small-heading">Activité récente</h4>{detail.data.transactions.slice(0,5).map((t:Transaction)=><div className="mini-history" key={t.id}><span className={`history-dot ${t.kind}`}/><span>{t.description||statusLabel[t.kind]}</span><small>{dateLabel(t.transaction_date)}</small><b className={t.kind==='income'?'income-text':''}>{money(t.amount_xof)}</b></div>)}</>:<div className="client-placeholder"><div className="empty-icon"><Users size={20}/></div><strong>La relation en chiffres</strong><p>Sélectionnez un client pour consulter son historique, ses paiements et son solde à recouvrer.</p></div>}</Panel></div>
    {modal&&<Modal title="Ajouter un client" subtitle="Votre mini CRM financier." onClose={()=>setModal(false)}><form className="form-grid" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);save.mutate({name:f.get('name'),email:f.get('email')||null,phone:f.get('phone')||null,payment_terms_days:Number(f.get('payment_terms_days')),reliability_score:f.get('reliability_score')?Number(f.get('reliability_score')):null,notes:f.get('notes')||''})}}><label className="field-label full-span">Nom du client<input name="name" required autoFocus/></label><label className="field-label">E-mail<input name="email" type="email"/></label><label className="field-label">Téléphone<input name="phone"/></label><label className="field-label">Délai de paiement<input name="payment_terms_days" type="number" min="0" defaultValue="30"/></label><label className="field-label">Fiabilité<select name="reliability_score"><option value="">Non évaluée</option>{[1,2,3,4,5].map(x=><option key={x} value={x}>{x} / 5</option>)}</select></label><label className="field-label full-span">Notes<textarea name="notes" rows={3}/></label>{save.error!=null&&<div className="full-span"><ErrorState error={save.error}/></div>}<div className="form-actions full-span"><Button type="button" variant="secondary" onClick={()=>setModal(false)}>Annuler</Button><Button type="submit" disabled={save.isPending}>{save.isPending?'Création…':'Créer le client'}</Button></div></form></Modal>}
  </div>
}

type QuoteRow={id:string;number:string;client_id:string;activity_id?:string;status:string;issue_date:string;accepted_at?:string|null;valid_until:string;total_xof:number;notes?:string;items:{designation:string;quantity:number;unit_price_xof:number;discount_xof:number;tax_rate:number}[]}
type InvoiceRow={id:string;number:string;client_id:string;client_name:string;issue_date:string;due_date:string;total_xof:number;paid_xof:number;balance_xof:number;status:string}

export function QuotesPage() {
  const client=useQueryClient();const [modal,setModal]=useState(false);const [editingQuote,setEditingQuote]=useState<QuoteRow|null>(null);const [payInvoice,setPayInvoice]=useState<InvoiceRow|null>(null)
  const quotes=useQuery({queryKey:['quotes'],queryFn:()=>api<QuoteRow[]>('/quotes')});const invoices=useQuery({queryKey:['invoices'],queryFn:()=>api<InvoiceRow[]>('/invoices')})
  const clients=useQuery({queryKey:['clients','filter'],queryFn:()=>api<Client[]>('/clients')}).data||[];const activities=useQuery({queryKey:['activities'],queryFn:()=>api<ActivityType[]>('/activities')}).data||[]
  const save=useMutation({mutationFn:({id,data}:{id?:string;data:any})=>api(`/quotes${id?`/${id}`:''}`,{method:id?'PUT':'POST',body:JSON.stringify(data)}),onSuccess:()=>{setModal(false);setEditingQuote(null);invalidate(client,[['quotes'],['dashboard']])}})
  const pay=useMutation({mutationFn:({id,data}:{id:string;data:any})=>api(`/invoices/${id}/payments`,{method:'POST',body:JSON.stringify(data)}),onSuccess:()=>{setPayInvoice(null);invalidate(client,[['invoices'],['transactions'],['dashboard'],['clients']])}})
  const action=async(path:string,method:string='POST',body?:any)=>{await api(path,{method,...(body?{body:JSON.stringify(body)}:{})});invalidate(client,[['quotes'],['invoices'],['dashboard']])}
  if(quotes.isLoading||invoices.isLoading)return <LoadingState/>;if(quotes.error)return <ErrorState error={quotes.error}/>
  const quoteRows=quotes.data||[], invoiceRows=invoices.data||[], totalOpen=invoiceRows.reduce((s,i)=>s+i.balance_xof,0), accepted=quoteRows.filter(q=>q.status==='accepted').length, conversion=quoteRows.filter(q=>q.status!=='draft').length?Math.round(100*accepted/quoteRows.filter(q=>q.status!=='draft').length):0
  const acceptanceDays=quoteRows.filter(q=>q.status==='accepted'&&q.accepted_at).map(q=>Math.round((Date.parse(q.accepted_at!)-Date.parse(q.issue_date))/86400000)).filter((days:number)=>Number.isFinite(days)&&days>=0)
  const avgAcceptanceDays=acceptanceDays.length?Math.round(acceptanceDays.reduce((sum:number,days:number)=>sum+days,0)/acceptanceDays.length):null
  return <div className="page-stack"><div className="inline-stats"><div><span>Devis actifs</span><strong>{quoteRows.filter(q=>['draft','sent','accepted'].includes(q.status)).length}</strong></div><div><span>Conversion des devis</span><strong>{conversion}%</strong></div><div><span>Factures à recouvrer</span><strong className="warning-text">{money(totalOpen)}</strong></div><div><span>Délai moyen d'acceptation</span><strong>{avgAcceptanceDays===null?'—':avgAcceptanceDays+' j'}</strong></div><div className="inline-actions"><AddButton onClick={()=>setModal(true)}>Créer un devis</AddButton></div></div>
    <Panel><SectionTitle title="Devis" subtitle="Suivi commercial et conversion en facture"/><div className="table-scroll"><table className="data-table"><thead><tr><th>RÉFÉRENCE</th><th>CLIENT</th><th>ÉMIS LE</th><th>VALIDITÉ</th><th>STATUT</th><th className="align-right">TOTAL</th><th>ACTIONS</th></tr></thead><tbody>{quoteRows.map(q=><tr key={q.id}><td><strong className="ref-code">{q.number}</strong></td><td>{clients.find(c=>c.id===q.client_id)?.name||'Client'}</td><td>{dateLabel(q.issue_date)}</td><td>{dateLabel(q.valid_until)}</td><td><span className={`status-pill status-${q.status}`}>{statusLabel[q.status]||q.status}</span></td><td className="amount-cell">{money(q.total_xof)}</td><td><div className="row-actions">{q.status==='draft'&&<><button className="icon-button small" title="Modifier" onClick={()=>{setEditingQuote(q);setModal(true)}}><Pencil size={14}/></button><button className="icon-button small danger-hover" title="Supprimer" onClick={()=>{if(window.confirm(`Supprimer le brouillon ${q.number} ?`))void api(`/quotes/${q.id}`,{method:'DELETE'}).then(()=>invalidate(client,[['quotes']]))}}><X size={14}/></button><button className="mini-action" onClick={()=>void action(`/quotes/${q.id}/status?status=sent`,'PATCH')}>Envoyer</button></>}{q.status==='sent'&&<button className="mini-action" onClick={()=>void action(`/quotes/${q.id}/status?status=accepted`,'PATCH')}>Accepter</button>}{q.status==='accepted'&&<button className="mini-action primary-mini" onClick={()=>void action(`/quotes/${q.id}/convert`)}>Facturer</button>}<button className="icon-button small" title="PDF" onClick={()=>void download(`/quotes/${q.id}/pdf`,`${q.number}.pdf`)}><Download size={14}/></button></div></td></tr>)}</tbody></table>{!quoteRows.length&&<EmptyState title="Pas encore de devis" text="Créez un devis pour suivre vos opportunités et préparer vos factures." icon={FileText}/>}</div></Panel>
    <Panel><SectionTitle title="Factures et règlements" subtitle="Factures émises, échéances et paiements reçus"/><div className="table-scroll"><table className="data-table"><thead><tr><th>FACTURE</th><th>CLIENT</th><th>ÉCHÉANCE</th><th>STATUT</th><th>TOTAL</th><th>RÉGLÉ</th><th>SOLDE</th><th>ACTIONS</th></tr></thead><tbody>{invoiceRows.map(inv=><tr key={inv.id}><td><strong className="ref-code">{inv.number}</strong></td><td>{inv.client_name}</td><td>{dateLabel(inv.due_date)}</td><td><span className={`status-pill status-${inv.status}`}>{statusLabel[inv.status]||inv.status}</span></td><td>{money(inv.total_xof)}</td><td className="income-text">{money(inv.paid_xof)}</td><td className={inv.balance_xof?'warning-text':''}>{money(inv.balance_xof)}</td><td><div className="row-actions">{inv.balance_xof>0&&<button className="mini-action primary-mini" onClick={()=>setPayInvoice(inv)}>Ajouter paiement</button>}<button className="icon-button small" title="PDF" onClick={()=>void download(`/invoices/${inv.id}/pdf`,`${inv.number}.pdf`)}><Download size={14}/></button></div></td></tr>)}</tbody></table>{!invoiceRows.length&&<EmptyState title="Aucune facture" text="Convertissez un devis accepté pour créer votre première facture." icon={FileSpreadsheet}/>}</div></Panel>
    {modal&&<QuoteModal initial={editingQuote} clients={clients} activities={activities} pending={save.isPending} error={save.error} onClose={()=>{setModal(false);setEditingQuote(null)}} onSave={data=>save.mutate({id:editingQuote?.id,data})}/>}
    {payInvoice&&<Modal title={`Règlement ${payInvoice.number}`} subtitle={`Solde restant : ${money(payInvoice.balance_xof)}`} onClose={()=>setPayInvoice(null)}><form className="form-grid" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);pay.mutate({id:payInvoice.id,data:{amount_xof:Number(f.get('amount_xof')),paid_at:f.get('paid_at'),payment_method:f.get('payment_method')}})}}><label className="field-label">Montant reçu (FCFA)<input name="amount_xof" type="number" min="1" max={payInvoice.balance_xof} defaultValue={payInvoice.balance_xof} required/></label><label className="field-label">Date de règlement<input name="paid_at" type="date" defaultValue={new Date().toISOString().slice(0,10)} required/></label><label className="field-label full-span">Moyen de paiement<select name="payment_method" required>{paymentMethods.map(([id,label])=><option key={id} value={id}>{label}</option>)}</select></label>{pay.error!=null&&<div className="full-span"><ErrorState error={pay.error}/></div>}<div className="form-actions full-span"><Button type="button" variant="secondary" onClick={()=>setPayInvoice(null)}>Annuler</Button><Button type="submit" disabled={pay.isPending}>{pay.isPending?'Enregistrement…':'Enregistrer le paiement'}</Button></div></form></Modal>}
  </div>
}

function QuoteModal({initial,clients,activities,pending,error,onClose,onSave}:{initial:QuoteRow|null;clients:Client[];activities:ActivityType[];pending:boolean;error:unknown;onClose:()=>void;onSave:(data:any)=>void}) {
  const [lines,setLines]=useState(initial?.items.length?initial.items.map(x=>({...x,quantity:Number(x.quantity)})):[{designation:'Prestation de conseil',quantity:1,unit_price_xof:0,discount_xof:0,tax_rate:0}])
  const total=lines.reduce((s,l)=>s+Math.max(0,Math.round(l.quantity*l.unit_price_xof)-l.discount_xof)+Math.round(Math.max(0,l.quantity*l.unit_price_xof-l.discount_xof)*l.tax_rate/100),0)
  return <Modal title={initial?'Modifier le devis':'Créer un devis'} subtitle={initial?initial.number:'La numérotation est automatique.'} onClose={onClose} wide><form className="form-grid" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);onSave({client_id:f.get('client_id'),activity_id:f.get('activity_id')||null,issue_date:f.get('issue_date'),valid_until:f.get('valid_until'),notes:f.get('notes')||'',items:lines})}}><label className="field-label">Client<select name="client_id" required defaultValue={initial?.client_id||''}><option value="" disabled>Sélectionner un client</option>{clients.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label className="field-label">Activité<select name="activity_id" defaultValue={initial?.activity_id||''}><option value="">Non affecté</option>{activities.map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</select></label><label className="field-label">Date d’émission<input name="issue_date" type="date" defaultValue={initial?.issue_date||new Date().toISOString().slice(0,10)} required/></label><label className="field-label">Valide jusqu’au<input name="valid_until" type="date" defaultValue={initial?.valid_until||new Date(Date.now()+30*86400000).toISOString().slice(0,10)} required/></label><div className="quote-lines full-span"><div className="quote-line-head"><span>PRESTATION</span><span>QTÉ</span><span>PRIX (FCFA)</span><span>REMISE</span><span>TVA %</span><span/></div>{lines.map((line,index)=><div className="quote-line" key={index}><input aria-label="Désignation" value={line.designation} onChange={e=>setLines(lines.map((l,i)=>i===index?{...l,designation:e.target.value}:l))} required/><input aria-label="Quantité" type="number" min=".01" step=".01" value={line.quantity} onChange={e=>setLines(lines.map((l,i)=>i===index?{...l,quantity:Number(e.target.value)}:l))}/><input aria-label="Prix unitaire" type="number" min="0" value={line.unit_price_xof} onChange={e=>setLines(lines.map((l,i)=>i===index?{...l,unit_price_xof:Number(e.target.value)}:l))}/><input aria-label="Remise" type="number" min="0" value={line.discount_xof} onChange={e=>setLines(lines.map((l,i)=>i===index?{...l,discount_xof:Number(e.target.value)}:l))}/><input aria-label="TVA" type="number" min="0" max="100" step=".1" value={line.tax_rate} onChange={e=>setLines(lines.map((l,i)=>i===index?{...l,tax_rate:Number(e.target.value)}:l))}/><button type="button" className="icon-button small" onClick={()=>setLines(lines.filter((_,i)=>i!==index))} disabled={lines.length===1} aria-label="Supprimer la ligne"><X size={14}/></button></div>)}<button className="text-link add-line" type="button" onClick={()=>setLines([...lines,{designation:'',quantity:1,unit_price_xof:0,discount_xof:0,tax_rate:0}])}><Plus size={14}/> Ajouter une ligne</button><div className="quote-total"><span>Total estimé</span><strong>{money(total)}</strong></div></div><label className="field-label full-span">Conditions et notes<textarea name="notes" rows={2} defaultValue={initial?.notes||''} placeholder="Validité, conditions de paiement…"/></label>{error!=null&&<div className="full-span"><ErrorState error={error}/></div>}<div className="form-actions full-span"><Button type="button" variant="secondary" onClick={onClose}>Annuler</Button><Button type="submit" disabled={pending}>{pending?'Enregistrement…':'Enregistrer le devis'}</Button></div></form></Modal>
}

export function ProfitabilityPage() {
  const filters=useFilters();const year=filters.year
  const query=useQuery({queryKey:['profitability',year],queryFn:()=>api<any>(`/profitability?year=${year}`)})
  const [cost,setCost]=useState(450000);const [margin,setMargin]=useState(35);const [hours,setHours]=useState(12);const [hourly,setHourly]=useState(25000)
  const price=useQuery({queryKey:['price',cost,margin,hours,hourly],queryFn:()=>api<any>(`/pricing/recommendation${queryString({cost_xof:cost,target_margin_pct:margin,hours,hourly_floor_xof:hourly})}`),enabled:cost>0&&margin>0&&margin<100})
  if(query.isLoading)return <LoadingState/>;if(query.error)return <ErrorState error={query.error}/>
  const d=query.data
  return <div className="page-stack"><div className="metric-subgrid compact-subgrid"><div className="submetric"><span>Revenus encaissés</span><strong>{money(d.revenue_xof)}</strong><small>Sur l’exercice {year}</small></div><div className="submetric"><span>Charges réglées</span><strong>{money(d.expenses_xof)}</strong><small>Coûts affectés et non affectés</small></div><div className="submetric"><span>Contribution nette</span><strong>{money(d.profit_xof)}</strong><small>Résultat de trésorerie</small></div><div className="submetric"><span>Point mort estimé</span><strong>{money(d.break_even_xof)}</strong><small>Selon le mix de coûts saisi</small></div></div>
    <div className="dashboard-grid dashboard-grid-main"><Panel><SectionTitle title="Marge par activité" subtitle="Revenus encaissés moins dépenses affectées"/><div className="chart-medium"><ResponsiveContainer width="100%" height="100%"><BarChart data={d.activities} layout="vertical" margin={{top:5,right:14,left:10,bottom:0}}><CartesianGrid horizontal={false} stroke="var(--line)"/><XAxis type="number" axisLine={false} tickLine={false} tickFormatter={shortMoney} tick={{fill:'var(--muted)',fontSize:10}}/><YAxis type="category" dataKey="name" width={120} axisLine={false} tickLine={false} tick={{fill:'var(--text)',fontSize:11}}/><Tooltip formatter={(v:any)=>money(Number(v))}/><Bar dataKey="profit_xof" name="Marge de trésorerie" fill="#E8763A" radius={[0,5,5,0]} barSize={22}/></BarChart></ResponsiveContainer></div></Panel><Panel><SectionTitle title="Matrice rentabilité / volume" subtitle="Marge et part de revenus par activité"/><div className="profit-matrix">{d.activities.map((a:any,i:number)=><div className="matrix-row" key={a.activity_id}><span className="matrix-color" style={{background:chartColors[i%chartColors.length]}}/><div className="matrix-label"><strong>{a.name}</strong><small>{a.hours?`${a.hours} h saisies`: 'Heures non renseignées'}</small></div><div className="matrix-bars"><div className="matrix-track"><i style={{width:`${Math.max(3,Math.min(100,100*a.revenue_xof/Math.max(d.revenue_xof,1)))}%`}}/></div><span>volume {d.revenue_xof?Math.round(100*a.revenue_xof/d.revenue_xof):0}%</span></div><div className="matrix-result"><b>{money(a.profit_xof)}</b><small>{a.revenue_per_hour_xof?`${money(a.revenue_per_hour_xof)}/h`:'— / h'}</small></div></div>)}{!d.activities.length&&<EmptyState/>}</div></Panel></div>
    <Panel><SectionTitle title="Marge par client et prestation" subtitle="Repérez les relations rentables et votre revenu horaire"/><div className="dashboard-grid client-profit-grid"><div><h3 className="small-heading">Clients</h3><div className="table-scroll"><table className="data-table"><thead><tr><th>CLIENT</th><th>REVENUS</th><th>CHARGES</th><th>MARGE</th><th>TAUX</th></tr></thead><tbody>{d.clients.map((c:any)=><tr key={c.client_id}><td>{c.name}</td><td>{money(c.revenue_xof)}</td><td>{money(c.expenses_xof)}</td><td><strong>{money(c.margin_xof)}</strong></td><td>{c.margin_pct}%</td></tr>)}</tbody></table></div></div><div><h3 className="small-heading">Types de prestation</h3>{d.services.map((s:any)=><div className="service-row" key={s.service_type}><div><strong>{s.service_type}</strong><small>{s.hours.toLocaleString('fr-FR')} h saisies</small></div><b>{money(s.revenue_xof)}</b><span>{money(s.revenue_per_hour_xof)} / h</span></div>)}{!d.services.length&&<p className="muted-copy">Enregistrez vos heures pour analyser le revenu par prestation.</p>}</div></div></Panel>
    <Panel className="pricing-panel"><div className="pricing-copy"><div className="pricing-icon"><TrendingUp size={19}/></div><div className="eyebrow">OUTIL DE DÉCISION</div><h2>Quel prix protège votre marge ?</h2><p>Définissez votre coût et votre marge cible pour obtenir un tarif plancher conseillé.</p><div className="pricing-form"><label className="field-label">Coût estimé (FCFA)<input type="number" min="1" value={cost} onChange={e=>setCost(Number(e.target.value))}/></label><label className="field-label">Marge cible (%)<input type="number" min="1" max="99" value={margin} onChange={e=>setMargin(Number(e.target.value))}/></label><label className="field-label">Heures de travail<input type="number" min=".1" step=".5" value={hours} onChange={e=>setHours(Number(e.target.value))}/></label><label className="field-label">Plancher horaire (FCFA)<input type="number" min="0" step="1000" value={hourly} onChange={e=>setHourly(Number(e.target.value))}/></label></div></div><div className="price-result"><span>PRIX CONSEILLÉ</span><strong>{money(price.data?.suggested_price_xof||0)}</strong><div><span>Marge estimée</span><b>{money(price.data?.estimated_margin_xof||0)} · {price.data?.estimated_margin_pct||0}%</b></div><small>Le prix respecte le plus élevé des deux seuils calculés.</small></div></Panel>
  </div>
}

const alertParameters:Record<string,{key:string;label:string;unit:string;defaultValue:number;step:number}>={client_concentration:{key:'threshold_pct',label:'Concentration client',unit:'%',defaultValue:40,step:1},category_spike:{key:'threshold_pct',label:'Hausse de d\u00e9penses',unit:'%',defaultValue:30,step:1},cash_forecast:{key:'threshold_months',label:'Horizon de tr\u00e9sorerie',unit:'mois',defaultValue:2,step:1},recurring_review:{key:'min_monthly_xof',label:'Charge \u00e0 revoir \u00e0 partir de',unit:'FCFA/mois',defaultValue:25000,step:1000},recurring_increase:{key:'threshold_pct',label:'Hausse d\u2019abonnement',unit:'%',defaultValue:20,step:1},activity_margin_decline:{key:'drop_pct',label:'Baisse de marge',unit:'points',defaultValue:15,step:1},activity_opportunity:{key:'min_revenue_xof',label:'CA minimum analys\u00e9',unit:'FCFA',defaultValue:100000,step:10000},savings_opportunity:{key:'min_savings_xof',label:'\u00c9conomie minimum',unit:'FCFA',defaultValue:10000,step:1000}}
export function AlertsPage() {
  const client = useQueryClient()
  const [status, setStatus] = useState('active')
  const [drafts, setDrafts] = useState<Record<string, string>>({})
  const query = useQuery({queryKey:['alerts',status], queryFn:()=>api<Alert[]>(`/alerts${queryString({status})}`)})
  const rules = useQuery({queryKey:['alert-rules'], queryFn:()=>api<any[]>('/alert-rules')})
  const update = useMutation({mutationFn:({id,newStatus}:{id:string;newStatus:string})=>api(`/alerts/${id}`,{method:'PATCH',body:JSON.stringify({status:newStatus})}),onSuccess:()=>invalidate(client,[['alerts'],['dashboard']])})
  const saveRule = useMutation({mutationFn:({rule,value}:{rule:any;value:number})=>{const config=alertParameters[rule.rule_type];return api(`/alert-rules/${rule.id}`,{method:'PATCH',body:JSON.stringify({...rule,parameters:{...rule.parameters,[config.key]:value}})})},onSuccess:()=>invalidate(client,[['alert-rules'],['alerts'],['dashboard']])})
  if(query.isLoading)return <LoadingState/>
  if(query.error)return <ErrorState error={query.error}/>
  const rows=query.data||[]
  const high=rows.filter(a=>a.severity==='high').length
  const labels:Record<string,string>={client_concentration:'D\u00e9pendance client',category_spike:'Hausse de d\u00e9penses',late_invoice:'Facture en retard',cash_forecast:'Tension de tr\u00e9sorerie',target_lag:'Retard sur objectif',recurring_review:'Utilit\u00e9 d\u2019une charge r\u00e9currente',recurring_increase:'Hausse d\u2019un abonnement',activity_margin_decline:'Marge par activit\u00e9',activity_opportunity:'Activit\u00e9 \u00e0 d\u00e9velopper',savings_opportunity:'\u00c9conomies potentielles'}
  const saveValue=(rule:any)=>{const config=alertParameters[rule.rule_type];const value=Number(drafts[rule.id]??rule.parameters?.[config.key]??config.defaultValue);if(Number.isFinite(value)&&value>=0)saveRule.mutate({rule,value})}
  return <div className="page-stack">
    <div className="alert-summary"><div className="alert-summary-icon"><BellRing size={21}/></div><div><span>VIGILANCE FINANCI\u00c8RE</span><strong>{rows.length?`${rows.length} alerte${rows.length>1?'s':''} \u00e0 examiner`:'Aucune alerte active'}</strong><p>{high?`${high} signalement${high>1?'s':''} n\u00e9cessitent votre attention.`:'Le moteur surveille vos donn\u00e9es et vos seuils.'}</p></div><div className="alert-summary-right"><b>{rows.length}</b><span>EN COURS</span></div></div>
    <div className="tab-strip">{[['active','Actives'],['acknowledged','Examin\u00e9es'],['resolved','R\u00e9solues'],['','Toutes']].map(([value,label])=><button key={label} className={status===value?'selected':''} onClick={()=>setStatus(value)}>{label}</button>)}</div>
    <div className="alerts-list">{rows.map(a=><Panel className={`alert-card alert-severity-${a.severity}`} key={a.id}><div className="alert-card-icon">{a.severity==='high'?<BellRing size={18}/>:<Activity size={18}/>}</div><div className="alert-card-main"><div className="alert-card-heading"><div><span className={`severity-pill severity-${a.severity}`}>{a.severity==='high'?'PRIORIT\u00c9 HAUTE':a.severity==='medium'?'\u00c0 SURVEILLER':'OPPORTUNIT\u00c9'}</span><h3>{a.title}</h3></div><time>{dateLabel(a.generated_at)}</time></div><p>{a.explanation}</p><div className="recommendation"><span>Action recommand\u00e9e</span>{a.recommendation}</div></div><div className="alert-card-actions">{a.status==='active'?<><button className="mini-action" onClick={()=>update.mutate({id:a.id,newStatus:'acknowledged'})}>Marquer examin\u00e9e</button><button className="icon-button small" title="R\u00e9soudre" onClick={()=>update.mutate({id:a.id,newStatus:'resolved'})}><Check size={15}/></button></>:<button className="mini-action" onClick={()=>update.mutate({id:a.id,newStatus:'active'})}>R\u00e9activer</button>}</div></Panel>)}{!rows.length&&<Panel><EmptyState title="Tout est sous contr\u00f4le" text="Aucune alerte ne correspond \u00e0 ce filtre. Les r\u00e8gles automatiques restent actives." icon={ShieldCheck}/></Panel>}</div>
    <Panel><SectionTitle title="R\u00e8gles de surveillance" subtitle="Ajustez les seuils et activez les signaux utiles \u00e0 votre activit\u00e9."/>{(rules.data||[]).map((rule:any)=>{const config=alertParameters[rule.rule_type];const current=config?(rule.parameters?.[config.key]??config.defaultValue):undefined;const draft=drafts[rule.id]??String(current??'');return <div className="rule-create-row" key={rule.id}><div className="rule-description"><strong>{labels[rule.rule_type]||rule.rule_type}</strong><small>{config?`${config.label} \u00b7 ${current} ${config.unit}`:'Surveillance automatique'}</small></div>{config&&<div className="rule-threshold-editor"><label>{config.label}<input type="number" min="0" step={config.step} value={draft} onChange={e=>setDrafts({...drafts,[rule.id]:e.target.value})}/><small>{config.unit}</small></label><button className="button button-secondary" disabled={saveRule.isPending||Number(draft)===Number(current)} onClick={()=>saveValue(rule)}>Enregistrer</button></div>}<button className={`toggle-switch ${rule.is_active?'on':''}`} aria-label={rule.is_active?'D\u00e9sactiver la r\u00e8gle':'Activer la r\u00e8gle'} onClick={()=>api(`/alert-rules/${rule.id}`,{method:'PATCH',body:JSON.stringify({...rule,is_active:!rule.is_active})}).then(()=>invalidate(client,[['alert-rules'],['alerts'],['dashboard']]))}><i/></button></div>})}{saveRule.error!=null&&<ErrorState error={saveRule.error}/>}</Panel>
  </div>
}

export function ForecastPage() {
  const [scenario,setScenario]=useState('realistic');const query=useQuery({queryKey:['forecast',scenario],queryFn:()=>api<any>(`/forecast?scenario=${scenario}`)})
  if(query.isLoading)return <LoadingState/>;if(query.error)return <ErrorState error={query.error}/>
  const data=query.data;const forecast=data.forecast.map((r:any)=>({...r,name:`M+${r.month_offset}`}));const scenarios=['optimistic','realistic','pessimistic']
  return <div className="page-stack"><div className="scenario-banner"><div><div className="eyebrow">TRÉSORERIE PRÉVISIONNELLE</div><h2>Gardez un temps d’avance.</h2><p>{data.method}</p></div><div className="scenario-switch">{scenarios.map(s=><button key={s} className={scenario===s?`selected scenario-${s}`:''} onClick={()=>setScenario(s)}>{s==='optimistic'?'Optimiste':s==='realistic'?'Réaliste':'Prudent'}</button>)}</div></div>
    <div className="metric-subgrid"><div className="submetric"><span>Solde d’ouverture</span><strong>{money(data.opening_cash_xof)}</strong><small>Trésorerie réalisée à date</small></div>{data.forecast.map((r:any)=><div className="submetric" key={r.month_offset}><span>Dans {r.month_offset} mois</span><strong className={r.cash_balance_xof<0?'warning-text':''}>{money(r.cash_balance_xof)}</strong><small>{money(r.income_xof)} d’entrées · {money(r.expenses_xof)} de sorties</small></div>)}</div>
    <Panel><SectionTitle title="Trajectoire de trésorerie" subtitle="Historique récent et projection mensuelle" action={<span className={`scenario-tag scenario-${scenario}`}>{scenario==='optimistic'?'SCÉNARIO OPTIMISTE':scenario==='realistic'?'SCÉNARIO RÉALISTE':'SCÉNARIO PRUDENT'}</span>}/><div className="forecast-chart"><ResponsiveContainer width="100%" height="100%"><LineChart data={[...data.history.map((r:any)=>({name:r.month.slice(5),solde:undefined,revenus:r.income_xof,depenses:r.expenses_xof})),...forecast.map((r:any)=>({name:r.name,solde:r.cash_balance_xof,revenus:r.income_xof,depenses:r.expenses_xof}))]} margin={{top:18,right:10,left:0,bottom:0}}><CartesianGrid vertical={false} stroke="var(--line)" strokeDasharray="4 5"/><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill:'var(--muted)',fontSize:11}}/><YAxis axisLine={false} tickLine={false} tick={{fill:'var(--muted)',fontSize:10}} tickFormatter={shortMoney}/><Tooltip formatter={(v:any)=>v===undefined?'—':money(Number(v))}/><Legend/><Line type="monotone" dataKey="revenus" name="Revenus historiques / projetés" stroke="#E8763A" strokeWidth={2} dot={false}/><Line type="monotone" dataKey="depenses" name="Dépenses historiques / projetées" stroke="#292927" strokeWidth={2} dot={false}/><Line type="monotone" dataKey="solde" name="Solde projeté" stroke="#668E84" strokeWidth={2.5} strokeDasharray="5 4" dot={{r:4}} connectNulls/></LineChart></ResponsiveContainer></div></Panel>
    <div className="forecast-note"><div className="note-icon"><Clock3 size={17}/></div><div><strong>Comment lire cette projection</strong><p>Le moteur extrapole la moyenne récente des entrées et sorties. Les factures non encaissées et les charges récurrentes ne sont pas encore intégrées à leur échéancier exact. Utilisez ces scénarios comme signal de pilotage, puis actualisez-les avec les règlements attendus.</p></div></div>
  </div>
}

export function ReportsPage() {
  const filters=useFilters();const client=useQueryClient();const [month,setMonth]=useState(new Date().getMonth()+1);const [budgetModal,setBudgetModal]=useState(false);const cats=useQuery({queryKey:['categories'],queryFn:()=>api<Category[]>('/categories?kind=expense')}).data||[]
  const dashboard=useQuery({queryKey:['dashboard','report',filters.year,month],queryFn:()=>api<DashboardData>(`/dashboard${queryString({year:filters.year,month})}`)})
  const save=useMutation({mutationFn:(data:any)=>api('/budgets',{method:'POST',body:JSON.stringify(data)}),onSuccess:()=>{setBudgetModal(false);invalidate(client,[['budgets'],['dashboard']])}})
  if(dashboard.isLoading)return <LoadingState/>;if(dashboard.error)return <ErrorState error={dashboard.error}/>
  const k=dashboard.data!.kpis;const monthNames=Array.from({length:12},(_,i)=>new Date(2020,i,1).toLocaleDateString('fr-FR',{month:'long'}))
  const start=`${filters.year}-${String(month).padStart(2,'0')}-01`;const end=new Date(filters.year,month,0).toISOString().slice(0,10)
  return <div className="page-stack"><div className="report-hero"><div className="report-hero-mark"><FileBarChart size={20}/></div><div><div className="eyebrow">RAPPORT FINANCIER · {filters.year}</div><h2>Synthèse mensuelle</h2><p>Indicateurs, créances et recommandations de votre activité.</p></div><div className="report-month"><label className="field-label">Période<select value={month} onChange={e=>setMonth(Number(e.target.value))}>{monthNames.map((m,i)=><option key={m} value={i+1}>{m} {filters.year}</option>)}</select></label></div><div className="report-downloads"><Button variant="secondary" onClick={()=>void download(`/reports/monthly.pdf${queryString({year:filters.year,month})}`,`finpilot-bilan-${filters.year}-${month}.pdf`)}><FileText size={15}/> PDF</Button><Button onClick={()=>void download(`/reports/monthly.xlsx${queryString({year:filters.year,month})}`,`finpilot-bilan-${filters.year}-${month}.xlsx`)}><FileSpreadsheet size={15}/> Excel</Button></div></div>
    <div className="report-kpis"><div><span>CA encaissé</span><strong>{money(k.revenue_xof)}</strong><small>{k.growth_mom_pct===null?'—':`${k.growth_mom_pct>0?'+':''}${k.growth_mom_pct}%`} vs période précédente</small></div><div><span>Dépenses réglées</span><strong>{money(k.expenses_xof)}</strong><small>Sorties du registre</small></div><div><span>Résultat net</span><strong>{money(k.net_profit_xof)}</strong><small>Marge {k.net_margin_pct}%</small></div><div><span>Créances ouvertes</span><strong>{money(k.receivables_xof)}</strong><small>{money(k.overdue_xof)} en retard</small></div></div>
    <div className="dashboard-grid report-grid"><Panel><SectionTitle title="Flux mensuels" subtitle="Encaissements et dépenses réglées"/><div className="chart-medium"><ResponsiveContainer width="100%" height="100%"><BarChart data={k.monthly} margin={{top:8,right:8,left:0,bottom:0}}><CartesianGrid vertical={false} stroke="var(--line)" strokeDasharray="4 5"/><XAxis dataKey="month" axisLine={false} tickLine={false} tickFormatter={(v:string)=>v.slice(5)} tick={{fill:'var(--muted)',fontSize:10}}/><YAxis axisLine={false} tickLine={false} tickFormatter={shortMoney} tick={{fill:'var(--muted)',fontSize:10}}/><Tooltip formatter={(v:any)=>money(Number(v))}/><Bar dataKey="income_xof" name="Revenus" fill="#E8763A" radius={[4,4,0,0]}/><Bar dataKey="expenses_xof" name="Dépenses" fill="#30302E" radius={[4,4,0,0]}/></BarChart></ResponsiveContainer></div></Panel><Panel><SectionTitle title="Indicateurs clés" subtitle="Repères de gestion de la période"/><div className="report-indicator-list"><div><span>DSO · délai de paiement</span><b>{k.dso_days} jours</b></div><div><span>Recouvrement</span><b>{k.collection_rate_pct}%</b></div><div><span>Conversion devis</span><b>{k.quote_conversion_pct}%</b></div><div><span>Délai moyen d'acceptation</span><b>{k.quote_acceptance_days===null?'—':k.quote_acceptance_days+' jours'}</b></div><div><span>Panier moyen</span><b>{money(k.average_basket_xof)}</b></div><div><span>Concentration client n° 1</span><b>{k.client_concentration_pct}%</b></div><div><span>Burn rate mensuel</span><b>{money(k.burn_rate_monthly_xof)}</b></div></div></Panel></div>
    <Panel><SectionTitle title="Budget vs réalisé" subtitle="Définissez une enveloppe par catégorie puis suivez les dépenses." action={<Button variant="secondary" onClick={()=>setBudgetModal(true)}><Plus size={15}/> Définir un budget</Button>}/>{dashboard.data?.budgets.length?<BudgetRows rows={dashboard.data.budgets}/>:<EmptyState title="Aucun budget pour cette période" text="Créez un budget mensuel par catégorie pour comparer vos objectifs aux dépenses réelles." icon={Wallet}/>}</Panel>
    {budgetModal&&<Modal title="Créer un budget" subtitle="Définissez une enveloppe pour une catégorie." onClose={()=>setBudgetModal(false)}><form className="form-grid" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);save.mutate({category_id:f.get('category_id'),period_start:`${f.get('period')}-01`,period_end:new Date(Number(String(f.get('period')).slice(0,4)),Number(String(f.get('period')).slice(5,7)),0).toISOString().slice(0,10),amount_xof:Number(f.get('amount_xof'))})}}><label className="field-label full-span">Catégorie<select name="category_id" required>{cats.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label className="field-label">Période<input name="period" type="month" defaultValue={`${filters.year}-${String(month).padStart(2,'0')}`} required/></label><label className="field-label">Budget (FCFA)<input name="amount_xof" type="number" min="1" required/></label>{save.error!=null&&<div className="full-span"><ErrorState error={save.error}/></div>}<div className="form-actions full-span"><Button type="button" variant="secondary" onClick={()=>setBudgetModal(false)}>Annuler</Button><Button type="submit" disabled={save.isPending}>Enregistrer</Button></div></form></Modal>}
  </div>
}

export function SettingsPage() {
  const client=useQueryClient();const query=useQuery({queryKey:['settings'],queryFn:()=>api<any>('/settings')});const rules=useQuery({queryKey:['recurring-rules'],queryFn:()=>api<any[]>('/recurring-rules')});const [message,setMessage]=useState('');const save=useMutation({mutationFn:(data:any)=>api('/settings',{method:'PUT',body:JSON.stringify(data)}),onSuccess:(data:any)=>{localStorage.setItem('finpilot_currency',data.currency);localStorage.setItem('finpilot_fx_rate',String(data.fx_rate||1));localStorage.setItem('finpilot_theme',data.theme||'light');setMessage('Préférences enregistrées.');client.invalidateQueries({queryKey:['settings']});window.setTimeout(()=>window.location.reload(),250)}})
  const recurring=useMutation({mutationFn:(data:any)=>api('/recurring-rules',{method:'POST',body:JSON.stringify(data)}),onSuccess:()=>client.invalidateQueries({queryKey:['recurring-rules']})})
  const runRecurring=useMutation({mutationFn:()=>api<any>('/recurring-rules/run',{method:'POST'}),onSuccess:(r:any)=>{setMessage(`${r.created} opération(s) récurrente(s) générée(s).`);invalidate(client,[['transactions'],['dashboard'],['recurring-rules']])}})
  const restore=useMutation({mutationFn:async(file:File)=>{const form=new FormData();form.append('file',file);return api<any>('/settings/restore',{method:'POST',body:form})},onSuccess:()=>{setMessage('Sauvegarde restaurée.');invalidate(client,[['dashboard'],['transactions'],['clients'],['quotes'],['invoices']])}})
  if(query.isLoading)return <LoadingState/>;if(query.error)return <ErrorState error={query.error}/>
  const s=query.data
  return <div className="page-stack"><Panel><SectionTitle title="Préférences de l’espace" subtitle="Identité, objectifs de pilotage et affichage."/><form className="settings-form" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);save.mutate({business_name:f.get('business_name'),currency:f.get('currency'),fx_rate:Number(f.get('fx_rate')),locale:'fr-FR',theme:f.get('theme'),monthly_target_xof:Number(f.get('monthly_target_xof')),annual_target_xof:Number(f.get('annual_target_xof')),legal_mentions:f.get('legal_mentions')})}}><div className="form-grid"><label className="field-label">Nom affiché<input name="business_name" defaultValue={s.business_name}/></label><label className="field-label">Devise d’affichage<select name="currency" defaultValue={s.currency}>{[['XOF','FCFA (XOF)'],['EUR','Euro (EUR)'],['USD','Dollar US (USD)'],['GBP','Livre (GBP)'],['CAD','Dollar canadien (CAD)']].map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></label><label className="field-label">Taux de conversion manuel<input name="fx_rate" type="number" min="0.000001" step="any" defaultValue={s.fx_rate||1}/><small>Nombre de FCFA pour 1 unité de la devise d’affichage. Gardez 1 pour XOF.</small></label><label className="field-label">Thème<select name="theme" defaultValue={s.theme||'light'}><option value="light">Clair</option><option value="dark">Sombre</option></select></label><label className="field-label">Objectif mensuel (FCFA)<input name="monthly_target_xof" type="number" min="0" defaultValue={s.monthly_target_xof}/></label><label className="field-label">Objectif annuel (FCFA)<input name="annual_target_xof" type="number" min="0" defaultValue={s.annual_target_xof}/></label><label className="field-label full-span">Mentions légales sur les PDF<textarea name="legal_mentions" rows={3} defaultValue={s.legal_mentions||''}/></label></div>{save.error!=null&&<ErrorState error={save.error}/>}<div className="form-actions settings-actions"><Button type="submit" disabled={save.isPending}>{save.isPending?'Enregistrement…':'Enregistrer les préférences'}</Button>{message&&<span className="success-copy"><Check size={14}/>{message}</span>}</div></form></Panel>
    <Panel><SectionTitle title="Opérations récurrentes" subtitle="Générez des charges ou revenus attendus selon une fréquence." action={<Button variant="secondary" onClick={()=>runRecurring.mutate()} disabled={runRecurring.isPending}><Clock3 size={14}/> Générer les échéances</Button>}/><div className="rule-create-row"><form className="recurring-form" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);recurring.mutate({kind:f.get('kind'),description:f.get('description'),amount_xof:Number(f.get('amount_xof')),frequency:f.get('frequency'),next_run:f.get('next_run'),activity_id:null,category_id:null,is_active:true});e.currentTarget.reset()}}><select name="kind"><option value="expense">Dépense</option><option value="income">Revenu</option></select><input name="description" placeholder="Ex. Abonnement logiciel" required/><input name="amount_xof" type="number" min="1" placeholder="Montant FCFA" required/><select name="frequency"><option value="monthly">Mensuelle</option><option value="weekly">Hebdomadaire</option><option value="quarterly">Trimestrielle</option><option value="yearly">Annuelle</option></select><input name="next_run" type="date" defaultValue={new Date().toISOString().slice(0,10)} required/><Button type="submit" disabled={recurring.isPending}><Plus size={14}/> Ajouter</Button></form></div>{rules.data?.length?<div className="recurring-list">{rules.data.map((r:any)=><div className="service-row" key={r.id}><div><strong>{r.description}</strong><small>{r.frequency} · prochaine date {dateLabel(r.next_run)}</small></div><b>{money(r.amount_xof)}</b><span className={r.kind==='income'?'income-text':''}>{r.kind==='income'?'Revenu attendu':'Charge prévue'}</span></div>)}</div>:<p className="muted-copy">Aucune règle récurrente. Ajoutez un abonnement ou une charge fixe ci-dessus.</p>}{recurring.error!=null&&<ErrorState error={recurring.error}/>}</Panel>
    <div className="dashboard-grid settings-utility-grid"><Panel><SectionTitle title="Sauvegarde du compte" subtitle="Exportez ou restaurez les données de cet espace."/><div className="backup-actions"><Button variant="secondary" onClick={()=>void download('/settings/backup','finpilot-backup.json')}><Download size={15}/> Télécharger la sauvegarde</Button><label className="button button-secondary import-button"><Upload size={15}/> Restaurer un fichier<input type="file" accept="application/json,.json" onChange={e=>{const file=e.target.files?.[0];if(file&&window.confirm('La restauration remplacera vos données financières actuelles. Continuer ?'))restore.mutate(file);e.currentTarget.value=''}}/></label></div>{restore.error!=null&&<ErrorState error={restore.error}/>}<small className="muted-copy">La restauration remplace les données de ce compte par celles de la sauvegarde sélectionnée.</small></Panel></div>
  </div>
}
